print('Transformer checkpoints must be accessible; offline Kaggle requires attached local model paths.',flush=True)
env=os.environ.copy();env['PYTHONUNBUFFERED']='1'
proc=subprocess.Popen([sys.executable,str(filename),'--parent-settings',str(settings)],
    env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,bufsize=1)
try:
    for line in proc.stdout:print(line,end='',flush=True)
    returncode=proc.wait()
except KeyboardInterrupt:
    proc.send_signal(signal.SIGINT)
    for line in proc.stdout:print(line,end='',flush=True)
    returncode=proc.wait()
print('Native experiment folder:', OPTIONS['OUTPUT_DIR'])
if returncode not in (0,75):
    raise RuntimeError('Baseline run failed or paused unexpectedly. Inspect output and RUN_ERROR.json.')
if returncode==75:
    print('PARTIAL: save all native output archives, reattach and resume with same code and settings.')
